<?php elseif($mode==='/mentor/experiences'): ?><a class="primary" href="<?= $this->h($this->url('/mentor/experience')) ?>">نوشتن تجربه جدید</a><div class="section"><?php foreach($rows as $r): ?><article class="card section"><h2><?= $this->h($r['title']) ?></h2><p>نسخه <?= $this->h($r['version_no']) ?> · <?= $this->status($r['status']) ?> <?= $r['public_version_id']===$r['version_id']?'· نسخه عمومی':'' ?></p><a href="<?= $this->h($this->url('/mentor/experience?id='.$r['id'])) ?>">باز کردن آخرین نسخه و ویرایش</a><?php if($r['status']==='draft'): ?><?= $this->start('/mentor/experience/submit') ?><input type="hidden" name="id" value="<?= $this->h($r['version_id']) ?>"><button>ارسال این نسخه برای بررسی</button></form><?php endif; ?></article><?php endforeach;if(!$rows): ?><p>هنوز تجربه‌ای ننوشته‌اید.</p><?php endif; ?></div>
<?php elseif($mode==='/mentor/experience'): $e=$experience??[]; ?><section class="card section"><h2>مستندات عمومی تجربه (اختیاری)</h2><p>فایل‌های انتخاب‌شده پس از تأیید و انتشار این نسخه، برای همه قابل دریافت خواهند بود. فایل خصوصی جلسه را اینجا بارگذاری نکنید. ابتدا فایل‌ها را بارگذاری و سپس متن را تکمیل کنید.</p><form method="post" enctype="multipart/form-data" data-content-upload data-api-url="<?= $this->h($this->url('/api/v1/mentor/evidence')) ?>" action="<?= $this->h($this->url('/mentor/evidence')) ?>"><input type="hidden" name="csrf" value="<?= $this->h($this->csrf) ?>"><input type="hidden" name="id" value="<?= $this->h($e['id']??'') ?>"><label for="evidence-file">تصویر یا PDF، حداکثر ۵ مگابایت</label><input id="evidence-file" type="file" name="attachment" accept=".png,.jpg,.jpeg,.pdf" required><button>بارگذاری مستند</button><p id="content-upload-status" role="status"></p></form></section><section class="card section"><?= $this->start('/mentor/experience/save') ?><?php require __DIR__.'/experience-fields.php'; ?></form></section><?php if(!empty($e['version_id'])&&!empty($case)&&in_array($e['status'],['draft','submitted'],true)): ?><section class="card section"><?= $this->start('/mentor/experience/approve') ?><input type="hidden" name="id" value="<?= $this->h($e['version_id']) ?>"><label class="check"><input type="checkbox" required>متن همین نسخه و مجوز نمایش آن را بررسی کرده‌ام و تأیید می‌کنم.</label><button>ثبت تأیید صاحب تجربه بدون ویرایش متن</button></form></section><?php endif; ?>
<?php else: ?><section class="card section"><h2>تنظیمات مشاوره</h2><?= $this->start('/mentor/calendar/settings') ?><?php foreach(['duration_minutes'=>'مدت جلسه به دقیقه (۱۵ تا ۱۲۰)','buffer_minutes'=>'فاصله بین جلسات به دقیقه','lead_hours'=>'حداقل فاصله رزرو به ساعت','daily_capacity'=>'ظرفیت روزانه'] as $k=>$label): ?><?= $this->field($k,$label,'number',(string)$settings[$k]) ?><?php endforeach; ?><?php foreach(['auto_accept'=>'پذیرش خودکار','acceptance_paused'=>'توقف دریافت درخواست جدید'] as $key=>$label): ?><label><?= $label ?><select name="<?= $key ?>"><option value="0" <?= !$settings[$key]?'selected':'' ?>>خیر</option><option value="1" <?= $settings[$key]?'selected':'' ?>>بله</option></select></label><?php endforeach; ?><label>گروه مجاز درخواست‌کننده<select name="access_scope"><option value="public" <?= $settings['access_scope']==='public'?'selected':'' ?>>همه کاربران واجد شرایط</option><option value="organization" <?= $settings['access_scope']==='organization'?'selected':'' ?>>فقط اعضای سازمان مشترک</option></select></label><button>ذخیره تنظیمات</button></form></section>
